import{_ as t,o as e,c as n,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const p=JSON.parse('{"title":"AI 内容生产","description":"","frontmatter":{"title":"AI 内容生产"},"headers":[],"relativePath":"md/ai-content/index.md","filePath":"md/ai-content/index.md","lastUpdated":1795424423000}'),o={name:"md/ai-content/index.md"};function i(l,a,s,d,c,h){return e(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="ai-内容生产" tabindex="-1">AI 内容生产 <a class="header-anchor" href="#ai-内容生产" aria-label="Permalink to &quot;AI 内容生产&quot;">​</a></h1><p>把 AI 用在内容上，效率提升来自<strong>流水线的稳定性</strong>，不来自某一次生成得多好。</p><h2 id="这个板块写什么" tabindex="-1">这个板块写什么 <a class="header-anchor" href="#这个板块写什么" aria-label="Permalink to &quot;这个板块写什么&quot;">​</a></h2><ul><li><a href="./pipeline.html">一条 AI 短视频流水线</a> —— 脚本、配音、画面、剪辑的分工与卡点</li><li><a href="./tts.html">TTS 做双人对白</a> —— 音色、停顿和批量生成的实际参数</li></ul><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><p>单条内容的生成成本已经趋近于零，稀缺的是<strong>选题判断</strong>和<strong>批量一致性的把控</strong>。</p><p>所以流水线设计的重点不是&quot;让 AI 写得多好&quot;，而是「让第 50 条和第 1 条质量一致」，以及「哪一步必须人工过一遍」。</p>',7)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
